private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index + 1);
        }
    } else {
        popType(descriptor, 0);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
        case 'F':
            // These types take up one slot
            return index + 1;
        case 'D':
        case 'J':
            // These types take up two slots
            return index + 1;
        case 'L':
            // Object type, skip to the end of the class name
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            return index + 1;
        case '[':
            // Array type, skip to the type of the array
            return popType(descriptor, index + 1);
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

