protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    while (!edgeList.isEmpty()) {
        E currentEdge = null;
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(startVertex) || graph.getEdgeTarget(edge).equals(startVertex)) {
                currentEdge = edge;
                break;
            }
        }
        if (currentEdge == null) {
            break; // In case of an invalid tour
        }
        edgeList.remove(currentEdge);

        if (graph.getEdgeSource(currentEdge).equals(startVertex)) {
            startVertex = graph.getEdgeTarget(currentEdge);
        } else {
            startVertex = graph.getEdgeSource(currentEdge);
        }
        vertexList.add(startVertex);
    }

    double weight = tour.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList, weight);
}

